"use client";

import {
  ColorPicker as ArkColorPicker,
  parseColor as parseColorArk,
} from "@ark-ui/react/color-picker";
import type React from "react";
import { cn } from "@/lib/utils";

export const parseColor = parseColorArk;

export const ColorArea = (
  props: React.ComponentProps<typeof ArkColorPicker.Root>
) => {
  const { className, children, ...rest } = props;

  return (
    <ArkColorPicker.Root
      className={cn("flex w-full flex-col gap-2 text-foreground", className)}
      data-slot="color-area-root"
      inline
      {...rest}
    >
      {children}
      <ArkColorPicker.HiddenInput />
    </ArkColorPicker.Root>
  );
};

export const ColorArea = (
  props: React.ComponentProps<typeof ArkColorPicker.Area>
) => {
  const { className, ...rest } = props;

  return (
    <ArkColorPicker.Area
      className={cn(
        "relative h-40 touch-none overflow-hidden rounded-md",
        className
      )}
      data-slot="color-area"
      {...rest}
    />
  );
};

export const ColorAreaBackground = (
  props: React.ComponentProps<typeof ArkColorPicker.AreaBackground>
) => {
  const { className, ...rest } = props;

  return (
    <ArkColorPicker.AreaBackground
      className={cn("size-full rounded-lg border", className)}
      data-slot="color-area-background"
      {...rest}
    />
  );
};

export const ColorAreaThumb = (
  props: React.ComponentProps<typeof ArkColorPicker.AreaThumb>
) => {
  const { className, ...rest } = props;

  return (
    <ArkColorPicker.AreaThumb
      className={cn(
        "-translate-1/2",
        "size-4 rounded-full border-2 border-white shadow-xs/5",
        "outline-none ring-border/64 focus-visible:ring-1",
        className
      )}
      data-slot="color-area-thumb"
      {...rest}
    />
  );
};
